/* From Uiverse.io by javierBarroso  - Tags: blue, purple, input, dark, search, modern, neon, transition */
.__UIV_SCOPE__ .input {
  min-width: 50px;
  width: 50px;
  transition-duration: 0.8s;
  transition-timing-function: cubic-bezier(0.175, 0.885, 0.32, 1.275);
  height: 50px;
  border-radius: 50px;
  border: none;
  padding: 20px;
  font-size: 18px;
  font-weight: 200;
  color: transparent;
  font-family: "Courier New", Courier, monospace;
  background: rgba(1, 1, 1, 0.9);
  box-shadow: 0 2px 5px rgba(20, 20, 20, 0);
  background: linear-gradient(0deg, #141414ec, #00000cea, #00000cea, #141414ec);
}

.__UIV_SCOPE__ .page {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  background-color: #111;
  z-index: -5;
  opacity: 1;
  background-image: linear-gradient(#18305527 1px, transparent 1px),
    linear-gradient(to right, #18305527 1px, #00000c 1px);
  background-size: 10px 10px;
}

.__UIV_SCOPE__ .input:focus {
  color: #999;
  width: 300px;
  outline-style: none;
}

.__UIV_SCOPE__ .search {
  display: flex;
  justify-content: center;
  align-items: center;
  width: fit-content;
  height: fit-content;
  position: relative;
}

.__UIV_SCOPE__ .search .i {
  position: absolute;
  inset: -1px;
  display: block;
  border-radius: 50px;
  pointer-events: none;
  z-index: -1;
  transition-duration: 0.8s;
  background: linear-gradient(
    -35deg,
    #f7f7f721 10%,
    transparent,
    rgba(243, 238, 243, 0.349) 80%
  );
}

.__UIV_SCOPE__ .search .span {
  width: 100%;
  height: 100%;
  background-color: #222;
  position: absolute;
  pointer-events: none;
  border-radius: 50px;
}

.__UIV_SCOPE__ .search .i:nth-child(3) {
  filter: blur(10px);
  background: linear-gradient(
    -35deg,
    #118cff 0%,
    transparent,
    transparent,
    #f1e 99%
  );
  inset: -2px;
}

.__UIV_SCOPE__ .search .i:nth-child(5) {
  background: linear-gradient(
    -35deg,
    #118cff 0%,
    transparent,
    transparent,
    #f1e 99%
  );
  z-index: -1;
}

.__UIV_SCOPE__ .search .icon {
  position: absolute;
  pointer-events: none;
  transition-duration: 0.8s;
  right: 0;
  width: 50px;
  height: 50px;
  margin: 0px;
  padding: 15px;
  border-radius: 50px;
  fill: #aaa;
}
